import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';

describe('turn usage [specs/hal-engine-config-hooks/spec.md#9]', () => {
  it('keeps each round usage when a provider reuses its usage object', async () => {
    const usage: UsageMetadata = {inputTokens: 2, outputTokens: 1, totalTokens: 3};
    let calls = 0;
    const provider: AIProvider = {
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        if (calls++ === 0) {
          yield {type: 'tool_use', toolCall: {id: 'one', name: 'lookup', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use', usage};
          return;
        }
        Object.assign(usage, {inputTokens: 7, outputTokens: 4, totalTokens: 11});
        yield {type: 'stop', stopReason: 'end_turn', usage};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const registry = new ToolRegistry();
    registry.register({name: 'lookup', description: 'Look up', inputSchema: {type: 'object'}}, async () => 'found');
    let reported: UsageMetadata | undefined;
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test'}), registry, {
      hooks: {afterModelResponse: async (_session, _text, totalUsage) => void (reported = totalUsage)},
    });
    await orchestrator.processMessage({sessionId: 'one', userId: 'user', entries: []});
    expect(reported).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
  });
});
EOF
